// Tanpa TypeScript — tidak ada kontrak
function hitungDiskon(harga, persen) {
  return harga - (harga * persen / 100);
}

// Dengan TypeScript — kontrak jelas
function hitungDiskon(harga: number, persen: number): number {
  return harga - (harga * persen / 100);
}

// TS langsung tangkap kesalahan:
hitungDiskon('150000', 20);
// ❌ Error: Argument of type 'string' is not assignable to 'number'

const hasil: string = hitungDiskon(150000, 20);
// ❌ Error: Type 'number' is not assignable to type 'string'

interface HasilCari {
  data: Produk[];
  total: number;
  halaman: number;
  totalHalaman: number;
}

// Return type yang jelas — developer tahu apa yang akan didapat
async function cariProduk(
  keyword: string,
  halaman: number
): Promise<HasilCari> {
  const response = await fetch(`/api/produk?q=${keyword}&page=${halaman}`);
  return response.json();
}

// TypeScript tahu persis struktur data yang dikembalikan
const hasil = await cariProduk('sepatu', 1);
console.log(hasil.totalHalaman); // ✅ TS tahu property ini ada
console.log(hasil.jumlahHalaman); // ❌ Error: property tidak ada

// Arrow function biasa
const tambah = (a: number, b: number): number => a + b;

// Arrow function dengan body
const formatRupiah = (angka: number): string => {
  return `Rp ${angka.toLocaleString('id-ID')}`;
};

// Tipe fungsi sebagai variabel
const kalikan: (a: number, b: number) => number = (a, b) => a * b;

// Atau pakai type alias (lebih readable)
type Operasi = (a: number, b: number) => number;
const bagi: Operasi = (a, b) => a / b;

// Tambah ? untuk jadikan opsional
function buatProfil(
  nama: string,
  email: string,
  bio?: string,        // opsional
  telepon?: string     // opsional
) {
  return {
    nama,
    email,
    bio: bio ?? 'Belum ada bio',
    telepon: telepon ?? '-'
  };
}

// Semua ini valid:
buatProfil('Budi', 'budi@mail.com');
buatProfil('Ani', 'ani@mail.com', 'Developer dari Bandung');
buatProfil('Cici', 'cici@mail.com', 'Designer', '081234567890');

// ❌ Tapi tidak boleh skip parameter wajib:
buatProfil('Dodi'); // Error: 'email' diperlukan

// Berikan nilai default langsung di signature
function hitungHarga(
  harga: number,
  pajak: number = 11,           // default 11%
  diskon: number = 0            // default tidak ada diskon
): number {
  const hargaSetelahDiskon = harga - (harga * diskon / 100);
  return hargaSetelahDiskon * (1 + pajak / 100);
}

hitungHarga(100000);        // harga=100000, pajak=11, diskon=0
hitungHarga(100000, 0);     // harga=100000, pajak=0, diskon=0
hitungHarga(100000, 11, 20); // harga=100000, pajak=11, diskon=20

// Perbedaan dengan optional:
// Optional (?): nilainya undefined kalau tidak diisi
// Default: nilainya default kalau tidak diisi — tidak perlu null check!

interface OpsiCari {
  halaman?: number;
  perHalaman?: number;
  urutkan?: 'asc' | 'desc';
  kolomUrut?: string;
}

// Destrukturisasi dengan default value
async function cariProduk(
  keyword: string,
  {
    halaman = 1,
    perHalaman = 20,
    urutkan = 'desc',
    kolomUrut = 'createdAt'
  }: OpsiCari = {} // default: objek kosong
) {
  // Semua parameter sudah punya nilai
  const url = `/api/produk?q=${keyword}&page=${halaman}&limit=${perHalaman}`;
  return fetch(url);
}

// Panggil dengan berbagai cara:
await cariProduk('kaos');
await cariProduk('kaos', { halaman: 2 });
await cariProduk('kaos', { urutkan: 'asc', kolomUrut: 'harga' });

// ...angka mengumpulkan semua argumen ke dalam array number[]
function jumlahkan(...angka: number[]): number {
  return angka.reduce((total, n) => total + n, 0);
}

jumlahkan(1, 2, 3);         // 6
jumlahkan(10, 20, 30, 40);  // 100
jumlahkan(5);               // 5
jumlahkan();                // 0

// Parameter biasa dulu, rest di akhir
function kirimEmail(
  pengirim: string,
  subjek: string,
  ...penerima: string[] // satu atau lebih penerima
) {
  console.log(`Dari: ${pengirim}`);
  console.log(`Subjek: ${subjek}`);
  console.log(`Ke: ${penerima.join(', ')}`);
}

kirimEmail('admin@mail.com', 'Meeting Besok', 'budi@mail.com');
kirimEmail('admin@mail.com', 'Promo', 'budi@mail.com', 'ani@mail.com', 'cici@mail.com');

// Rest parameter: kumpulkan banyak argumen jadi array
function log(level: string, ...pesan: string[]) {
  console.log(`[${level}]`, pesan.join(' '));
}

// Spread operator: sebar array jadi argumen
const pesanLog = ['Server', 'mulai', 'berjalan'];
log('INFO', ...pesanLog); // sama dengan log('INFO', 'Server', 'mulai', 'berjalan')

// void — fungsi selesai, tidak ada return value
function simpanLog(pesan: string): void {
  console.log(`[${new Date().toISOString()}] ${pesan}`);
  // tidak ada return
}

// Boleh return undefined secara eksplisit
function resetForm(): void {
  formData = {};
  return; // return tanpa nilai, atau return undefined
}

// Event handler hampir selalu void
document.addEventListener('click', (e: MouseEvent): void => {
  console.log('Diklik!');
});

// never — fungsi tidak pernah return
function lemparError(pesan: string): never {
  throw new Error(pesan);
  // Baris ini tidak pernah dicapai
}

function loopSelamanya(): never {
  while (true) {
    prosesAntrian();
  }
  // Baris ini tidak pernah dicapai
}

// Penggunaan praktis: fungsi helper untuk assert
function assertTidakMungkin(nilai: never): never {
  throw new Error(`Nilai tidak terduga: ${JSON.stringify(nilai)}`);
}

