// void: fungsi BISA dipanggil, hasilnya tidak dipakai
const logFn: () => void = () => console.log('log');
logFn(); // bisa dipanggil, tidak error

// never: fungsi tidak akan pernah return ke caller
const errorFn: () => never = () => { throw new Error(); };
errorFn(); // bisa dipanggil, tapi eksekusi setelah ini tidak akan terjadi

// Implikasi praktis:
function cekNilai(nilai: string | null): string {
  if (nilai === null) {
    lemparError('Nilai tidak boleh null'); // return type: never
    // TypeScript tahu: kalau sampai sini, eksekusi berhenti
    // Jadi di bawah ini TypeScript TAHU nilai adalah string
  }
  return nilai.toUpperCase(); // ✅ aman karena null sudah di-handle oleh never
}

