// Definisikan semua signature yang valid
function proses(input: string): string;
function proses(input: number): number;
function proses(input: string[]): string;

// Implementasi — harus handle semua kasus
function proses(input: string | number | string[]): string | number {
  if (typeof input === 'string') {
    return input.toUpperCase();
  }
  if (typeof input === 'number') {
    return input * 2;
  }
  return input.join(', ');
}

// TypeScript pilih return type yang tepat berdasarkan argumen:
const a = proses('halo');      // tipe: string
const b = proses(42);          // tipe: number
const c = proses(['a', 'b']);  // tipe: string

// Fungsi yang bisa terima Date atau string,
// dan return format yang berbeda
function formatTanggal(tanggal: Date): string;
function formatTanggal(tanggal: Date, format: 'pendek'): string;
function formatTanggal(tanggal: Date, format: 'panjang'): string;
function formatTanggal(tanggal: Date, format: 'timestamp'): number;

// Implementasi
function formatTanggal(
  tanggal: Date,
  format: 'pendek' | 'panjang' | 'timestamp' = 'pendek'
): string | number {
  const options = {
    pendek: { day: '2-digit', month: '2-digit', year: '2-digit' },
    panjang: { day: 'long', month: 'long', year: 'numeric' }
  } as const;

  if (format === 'timestamp') return tanggal.getTime();
  return tanggal.toLocaleDateString('id-ID', options[format]);
}

// Penggunaan:
const d = new Date();
formatTanggal(d);              // string: '09/05/26'
formatTanggal(d, 'panjang');  // string: 'Sabtu, 9 Mei 2026'
formatTanggal(d, 'timestamp'); // number: 1715299200000
